class MaxTracker {
    private final AtomicLong max = new AtomicLong(Long.MIN_VALUE);

    void offer(long amount) {
        max.accumulateAndGet(amount, Math::max);   // CAS loop inside
    }

    long max() { return max.get(); }
}

